                fn from_str(s: &str) -> Result<Self, Self::Err> {
                    match s {
                        $(
                            stringify!([<$name:snake>]) => {
                                Ok(Self::[<$name:camel>])
                            },
                        )*
                        _ => Err(Error::UnknownFeature(s.to_string())),
                    }
                }
