    ($vec_name:ident, ($arg_name_head:ident: reg, $($arg_name:ident: $arg_ty:tt,)*)) => {
        let _ = $arg_name_head;
        push_immediate_idents!($vec_name, ($($arg_name: $arg_ty,)*))
