        // the assertions inside the async block are what matter
        block_on_any_runtime(async {
            let pinned = Pinned {
                source: Source {
                    name: "nonexistent_test_package".to_string(),
                    version: semver::Version::new(1, 0, 0),
                    namespace: Namespace::Flat,
                },
