                cid: Cid::from_str("QmdMVqLqpba2mMB5AUjYCxubC6tLGevQFunpBkbC2UbrKS").unwrap(),
            };

            // Get the expected package directory path
            let expected_path = registry_package_dir(
                &pinned.source.namespace,
                &pinned.source.name,
                &pinned.source.version,
