        })
        .to_string()
    }

    fn rc_status_json(rc_path: &str, allowed: Option<u8>) -> Value {
        match allowed {
            Some(allowed) => json!({
                "allowed": allowed,
                "path": rc_path,
            }),
            None => Value::Null,
        }
    }
